mapper.sql:
WHERE w.state IN ('INDEXED', 'NOTIFIED')
 AND w.codes @> ARRAY[#{f.code}]::text[]
 AND w.taxgroups @> ARRAY[#{f.taxgroup}]::text[]
 AND s.subfields @> ARRAY[#{f.subfield}]::text[]
 AND s.journal_type = #{f.journalType}
 AND s.tier = #{f.tier}
 AND s.oa_model = #{f.oa}
 AND s.country = #{f.country}
 AND w.source_id = #{f.source}
  AND w.year >= #{f.yearFrom} 
  AND w.year <= #{f.yearTo} 
 AND COALESCE(w.has_acts, false) = #{f.hasActs}
 AND EXISTS (SELECT 1 FROM mention m WHERE m.work_id = w.id AND m.act_type = #{f.actType})
 AND w.fts @@ websearch_to_tsquery('simple', #{f.q})

  AND EXISTS (SELECT 1 FROM work_name wn WHERE wn.work_id = w.id AND wn.taxon_path @> ARRAY[#{f.taxon}]::text[]
    AND NOT wn.only_reference  AND wn.main_subject)


  AND EXISTS (SELECT 1 FROM work_name wn WHERE wn.work_id = w.id AND wn.name_string_id = #{f.name}
     AND wn.main_subject)


  AND EXISTS (SELECT 1 FROM work_name wn WHERE wn.work_id = w.id AND wn.main_subject)

